async function assignMoreOutbound(){
 if(!readyOutbounds.length)return;
 const w=workspace,day=today,items=readyOutbounds.slice(0,extraOutboundCount);
 await run(async()=>{
  let moved=0,unscheduledAdded=0;
  try{
   // Recheck the source-of-truth before assigning: someone may have logged a reply or paused a company.
   const [freshContacts,freshActivities]=await Promise.all([
    client()!.from('contacts').select('*').eq('workspace_id',w),
    client()!.from('activities').select('*').eq('workspace_id',w)
   ]);
   if(freshContacts.error)throw freshContacts.error;
   if(freshActivities.error)throw freshActivities.error;
   const verifiedReady=readyOutboundCandidates(freshContacts.data as Contact[],freshActivities.data as Activity[],day);
   const allowed=new Map(verifiedReady.map(c=>[c.id,c]));
   for(const person of items){
    if(latestWorkspace.current!==w)break;
    const fresh=allowed.get(person.id);
    if(!fresh||fresh.next_date!==person.next_date||fresh.notes!==person.notes)continue;
    const fromUnscheduled=person.next_date===null;
    const payload={next_date:day,notes:pullForwardNotes(person,day),
     ...(fromUnscheduled?{next_action:'LinkedIn: verify profile and inbox; send a researched DM if connected, otherwise a connection request'}:{})};
    let req=client()!.from('contacts').update(payload)
     .eq('workspace_id',w).eq('id',person.id).eq('status','New').eq('notes',person.notes);
    req=person.next_date===null?req.is('next_date',null):req.eq('next_date',person.next_date);
    const {data,error}=await req.select('*').maybeSingle();
    if(error)throw error;
    if(data){moved++;if(fromUnscheduled)unscheduledAdded++;updateContact(w,data as Contact)}
   }
  }catch(e){await load(w);throw Error(moved+' outbounds assigned before error: '+errText(e))}
  if(latestWorkspace.current!==w)return;
  if(moved!==items.length)await load(w);
  setMessage(moved?moved+' LinkedIn prospect'+(moved===1?'':'s')+' assigned to today'+(unscheduledAdded?' · '+unscheduledAdded+' from unscheduled research':'')+(moved<items.length?' · some records changed; queue refreshed':''):'No prospects assigned. Records changed; refresh and retry.');
 })
}
