function parse(text:string){const trimmed=text.trim();if(!trimmed){setPreview([]);return}const first=trimmed.split(/\r?\n/)[0];if(first.includes('\t')||(/(?:^|,)\s*(?:name|full name|first name|email|company|linkedin|phone)\s*(?:,|$)/i.test(first)&&first.includes(','))){const parsed=Papa.parse<Record<string,string>>(trimmed,{header:true,skipEmptyLines:'greedy',delimiter:first.includes('\t')?'\t':','});setPreview(parsed.data.map(mapRow).filter(r=>r.name));}else setPreview(trimmed.split(/\n\s*\n/).map(parseLoose).filter(r=>r.name))}
async function fileImport(file:File){await run(async()=>{if(file.size>10*1024*1024)throw Error('File limit is 10 MB. Split larger exports.');if(file.name.toLowerCase().endsWith('.xlsx')){const Excel=await import('exceljs');const wb=new Excel.Workbook();await wb.xlsx.load(await file.arrayBuffer());const sheet=wb.worksheets[0];if(!sheet)throw Error('Empty workbook');const headers:Record<number,string>={};sheet.getRow(1).eachCell((v,i)=>headers[i]=v.text);const rows:ReturnType<typeof mapRow>[]=[];sheet.eachRow((row,i)=>{if(i===1)return;const obj:Record<string,string>={};row.eachCell((v,j)=>{if(headers[j])obj[headers[j]]=v.text});const r=mapRow(obj);if(r.name)rows.push(r)});setPreview(rows)}else if(file.name.toLowerCase().endsWith('.csv')||file.name.toLowerCase().endsWith('.tsv'))parse(await file.text());else throw Error('Choose .xlsx, .csv or .tsv.');setMessage('Review imported rows before saving')})}
async function saveImport(){await run(async()=>{const rows=preview.filter((r,i)=>!dupRows[i]&&r.name).map(r=>{const v=cleanContact(r);return {...v,type:types.includes(v.type as typeof types[number])?v.type:'Direct customer',priority:priorities.includes(v.priority as typeof priorities[number])?v.priority:'Medium',workspace_id:workspace}});if(!rows.length)throw Error('No new rows to import.');let saved=0;try{for(let i=0;i<rows.length;i+=100){const {error}=await client()!.from('contacts').insert(rows.slice(i,i+100));if(error)throw error;saved+=Math.min(100,rows.length-i)}}catch(e){await load(workspace);throw Error(saved+' rows saved before error: '+errText(e))}setPreview([]);setPaste('');setMessage(saved+' prospects imported');await load(workspace);go('Prospects')})}
